import React, { useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";

import AdminBookingTable from "../components/AdminBookingTable";
import AdminLayout from "../components/AdminLayout";
import api from "../services/api";
import { formatErrorMessage } from "../utils/errorMessages";

const AdminHistory = () => {
  const [history, setHistory] = useState(null);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const loadHistory = async () => {
      try {
        const response = await api.get("/admin/history");
        setHistory(response.data || []);
      } catch (error) {
        setMessage(formatErrorMessage(error.response?.data?.detail, "Could not load history."));
        setHistory([]);
      }
    };

    loadHistory();
  }, []);

  const processedBookings = useMemo(
    () => history?.filter((booking) => ["approved", "rejected"].includes(booking.status)) || history,
    [history]
  );

  return (
    <AdminLayout title="History" subtitle="Approved and rejected records from your block.">
      {message ? <motion.div className="alert info" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>{String(message)}</motion.div> : null}
      <AdminBookingTable bookings={processedBookings} />
    </AdminLayout>
  );
};

export default AdminHistory;
